pub assume_specification<T, F: FnOnce(&T, &T) -> core::cmp::Ordering>[ core::cmp::max_by ](
    v1: T,
    v2: T,
    compare: F,
) -> (result: T)
    requires
        compare.requires((&v1, &v2)),
    ensures
        exists|ordering: core::cmp::Ordering| {
            &&& #[trigger] compare.ensures((&v1, &v2), ordering)
            &&& result == if ordering == core::cmp::Ordering::Greater { v1 } else { v2 }
        },
;

pub assume_specification<T, F, K>[ core::cmp::max_by_key ](
    v1: T,
    v2: T,
    f: F,
) -> (result: T)
where
    F: FnMut(&T) -> K,
    K: core::cmp::Ord,
    requires
        f.requires((&v2,)),
        f.requires((&v1,)),
    ensures
        exists|key2: K| {
            &&& #[trigger] f.ensures((&v2,), key2)
            &&& exists|key1: K| {
                &&& #[trigger] f.ensures((&v1,), key1)
                &&& exists|is_less: bool| {
                    &&& #[trigger] call_ensures(
                        <K as core::cmp::PartialOrd>::lt,
                        (&key2, &key1),
                        is_less,
                    )
                    &&& result == if is_less { v1 } else { v2 }
                }
            }
        },
;

